// This code has been fully generated by an AI.

package routesvg

import (
	"math"
	"strconv"
	"strings"
	"testing"

	"github.com/paulmach/orb"

	"github.com/stefanluchs/my-velo/internal/geo"
)

func encode(pts ...orb.Point) string { return geo.EncodePolyline(orb.LineString(pts)) }

func coords(t *testing.T, d string) [][2]float64 {
	t.Helper()
	var out [][2]float64
	for _, seg := range strings.FieldsFunc(d, func(r rune) bool { return r == 'M' || r == 'L' }) {
		xy := strings.Split(seg, ",")
		x, err1 := strconv.ParseFloat(xy[0], 64)
		y, err2 := strconv.ParseFloat(xy[1], 64)
		if len(xy) != 2 || err1 != nil || err2 != nil {
			t.Fatalf("bad segment %q in %q", seg, d)
		}
		out = append(out, [2]float64{x, y})
	}
	return out
}

func TestFromPolylineFitsAndOrients(t *testing.T) {
	// East–west line with a detour to the north at the end.
	r, ok := FromPolyline(encode(orb.Point{12.80, 48.20}, orb.Point{12.90, 48.20}, orb.Point{12.90, 48.22}))
	if !ok {
		t.Fatal("route expected")
	}
	if !strings.HasPrefix(r.D, "M") || strings.Count(r.D, "L") != 2 {
		t.Fatalf("path %q", r.D)
	}
	for _, p := range coords(t, r.D) {
		if p[0] < pad-0.05 || p[0] > Width-pad+0.05 || p[1] < pad-0.05 || p[1] > Height-pad+0.05 {
			t.Errorf("point %v outside padded viewBox", p)
		}
	}
	// Wider than high: fills the width, centred vertically.
	if r.StartX != pad || r.EndX != Width-pad {
		t.Errorf("x range %v..%v", r.StartX, r.EndX)
	}
	if r.EndY >= r.StartY {
		t.Errorf("north must point up: start y %v, end y %v", r.StartY, r.EndY)
	}
}

func TestFromPolylineKeepsAspectRatio(t *testing.T) {
	// A square in Mercator space must stay square.
	lat0, lat1 := 48.0, 48.0
	y0 := math.Log(math.Tan(math.Pi/4 + lat0*math.Pi/360))
	lat1 = (2*math.Atan(math.Exp(y0+0.01*math.Pi/180)) - math.Pi/2) * 180 / math.Pi
	r, ok := FromPolyline(encode(orb.Point{12, lat0}, orb.Point{12.01, lat0}, orb.Point{12.01, lat1}, orb.Point{12, lat1}, orb.Point{12, lat0}))
	if !ok {
		t.Fatal("route expected")
	}
	var minX, maxX, minY, maxY = math.Inf(1), math.Inf(-1), math.Inf(1), math.Inf(-1)
	for _, p := range coords(t, r.D) {
		minX, maxX = math.Min(minX, p[0]), math.Max(maxX, p[0])
		minY, maxY = math.Min(minY, p[1]), math.Max(maxY, p[1])
	}
	if w, h := maxX-minX, maxY-minY; math.Abs(w-h) > 1 || math.Abs(h-(Height-2*pad)) > 0.2 {
		t.Errorf("square became %.1f × %.1f", w, h)
	}
	if c := (minX + maxX) / 2; math.Abs(c-Width/2) > 0.2 {
		t.Errorf("not centred horizontally: %.1f", c)
	}
}

func TestFromPolylineSimplifies(t *testing.T) {
	var pts []orb.Point
	for i := range 2000 {
		pts = append(pts, orb.Point{12 + float64(i)*1e-4, 48 + 1e-5*float64(i%2)})
	}
	r, ok := FromPolyline(encode(pts...))
	if !ok {
		t.Fatal("route expected")
	}
	if n := strings.Count(r.D, "L"); n > 20 {
		t.Errorf("jitter below tile resolution must be dropped, got %d segments", n)
	}
}

func TestFromPolylineDegenerate(t *testing.T) {
	for name, poly := range map[string]string{
		"empty":   "",
		"invalid": "\x01",
		"single":  encode(orb.Point{12, 48}),
		"same":    encode(orb.Point{12, 48}, orb.Point{12, 48}),
	} {
		if _, ok := FromPolyline(poly); ok {
			t.Errorf("%s: no route expected", name)
		}
	}
	if r, ok := FromPolyline(encode(orb.Point{12, 48}, orb.Point{12, 48.01})); !ok || r.StartX != Width/2 {
		t.Errorf("north–south line must be centred: %+v %v", r, ok)
	}
}
